@app.post("/api/loyalty/redeem")
def loyalty_redeem():
    user = _current_member()
    if not user:
        return jsonify(error="login required"), 401
    data = request.get_json(force=True) or {}
    reward_type = (data.get("reward_type") or "").strip()
