# ---------------- admin: manage staff logins ----------------

@app.post("/api/admin/staff")
def admin_create_staff():
    user = _current_member()
    if not _is_admin(user):
        return jsonify(error="admin required"), 403
    data = request.get_json(force=True) or {}
    email = (data.get("email") or "").strip().lower()
    name = (data.get("name") or "").strip()
    password = data.get("password") or ""
    if not EMAIL_RE.match(email):
        return jsonify(error="valid email required"), 400
    if len(password) < 8:
        return jsonify(error="password must be at least 8 characters"), 400
    conn = db()
    # A deactivated staff email can be reused: reactivate the old row so their
    # Kernel balance, history, and referral code are preserved (points never reset).
    old = conn.execute(
        "SELECT id, referral_code FROM staff WHERE email = ? AND active = 0", (email,)
    ).fetchone()
    if old:
        conn.execute(
            "UPDATE staff SET name = ?, password_hash = ?, verified = 0,"
            " active = 1 WHERE id = ?",
            (name or email.split("@")[0], generate_password_hash(password), old["id"]),
        )
        staff_id = old["id"]
        vtoken = secrets.token_urlsafe(32)
        vexpires = (datetime.now(timezone.utc) + timedelta(hours=48)).isoformat()
        conn.execute(
            "INSERT INTO staff_verification_tokens (token, staff_id, expires_at) VALUES (?, ?, ?)",
            (vtoken, staff_id, vexpires),
        )
        _erp_staff_audit(conn, user["email"], "staff.reactivated", "staff",
                         staff_id, "reactivated %s (%s)" % (name or email, email))
        conn.commit()
        conn.close()
        verify_url = f"{SITE_URL}/#staff-verify?token={vtoken}"
        try:
            send_email(
                email,
                "Your Pop-A-Licious staff account",
                f"Hi {name or 'there'},\n\nYour staff account has been reactivated.\n"
                f"Click below to verify your account and set your password:\n{verify_url}\n\n"
                f"This link expires in 48 hours.\n",
            )
        except Exception:
            pass
        return jsonify(ok=True, reactivated=True)
    try:
        ref_code = "STF-" + secrets.token_hex(3).upper()
        cur = conn.execute(
            "INSERT INTO staff (email, name, password_hash, referral_code, verified, created_at, perms_migrated) VALUES (?, ?, ?, ?, 0, ?, 1)",
            (email, name or email.split("@")[0], generate_password_hash(password),
             ref_code, datetime.now(timezone.utc).isoformat()),
        )
        staff_id = cur.lastrowid
        # Verification token for the staff welcome email.
        vtoken = secrets.token_urlsafe(32)
        vexpires = (datetime.now(timezone.utc) + timedelta(hours=48)).isoformat()
        conn.execute(
            "INSERT INTO staff_verification_tokens (token, staff_id, expires_at) VALUES (?, ?, ?)",
            (vtoken, staff_id, vexpires),
        )
        _erp_staff_audit(conn, user["email"], "staff.created", "staff",
                         staff_id, "created %s (%s)" % (name or email, email))
        conn.commit()
    except sqlite3.IntegrityError:
        conn.close()
        return jsonify(error="that staff email already exists"), 409
    conn.close()
    verify_url = f"{SITE_URL}/#staff-verify?token={vtoken}"
    try:
        send_email(
            email,
            "Your Pop-A-Licious staff account",
            f"Hi {name or 'there'},\n\nYour staff account has been created.\n"
            f"Click below to verify your account and set your password:\n{verify_url}\n\n"
            f"This link expires in 48 hours.\n",
        )
    except Exception:
        pass
    return jsonify(ok=True)

# ---------------- admin: per-staff ERP permissions ----------------
# Only Matt/DJ (admins) can list or assign permissions. Assignments take
# effect immediately on the backend; staff see new menus next sign-in.
@app.get("/api/erp/admin/staff-permissions")
def erp_admin_list_staff_perms():
    user = _current_member()
    if not _is_admin(user):
        return jsonify(error="admin required"), 403
    conn = db()
    rows = conn.execute(
        "SELECT id, name, email, active FROM staff ORDER BY name, email").fetchall()
    out = []
    for r in rows:
        perms = [p[0] for p in conn.execute(
            "SELECT perm FROM erp_staff_perms WHERE staff_id = ? ORDER BY perm",
            (r["id"],)).fetchall()]
        out.append({"id": r["id"], "name": r["name"], "email": r["email"],
                    "active": bool(r["active"]), "perms": perms})
    conn.close()
    return jsonify(staff=out, grantable=list(_ERP_GRANTABLE_PERMS))


@app.put("/api/erp/admin/staff-permissions/<int:staff_id>")
def erp_admin_set_staff_perms(staff_id):
    user = _current_member()
    if not _is_admin(user):
        return jsonify(error="admin required"), 403
    data = request.get_json(force=True) or {}
    perms = data.get("perms")
    if not isinstance(perms, list) or any(
            not isinstance(p, str) or p not in _ERP_GRANTABLE_PERMS for p in perms):
        return jsonify(error="perms must be a list of valid permissions"), 400
    conn = db()
    row = conn.execute("SELECT id, name, email FROM staff WHERE id = ?",
                       (staff_id,)).fetchone()
    if not row:
        conn.close()
        return jsonify(error="staff member not found"), 404
    old_perms = {p[0] for p in conn.execute(
        "SELECT perm FROM erp_staff_perms WHERE staff_id = ?", (staff_id,)).fetchall()}
    new_perms = sorted(set(perms))
    conn.execute("DELETE FROM erp_staff_perms WHERE staff_id = ?", (staff_id,))
    for perm in new_perms:
        conn.execute("INSERT INTO erp_staff_perms (staff_id, perm) VALUES (?, ?)",
                     (staff_id, perm))
    granted = sorted(set(new_perms) - old_perms)
    revoked = sorted(old_perms - set(new_perms))
    detail = "%s (%s): " % (row["name"] or row["email"], row["email"])
    parts = []
    if granted:
        parts.append("granted: " + ", ".join(granted))
    if revoked:
        parts.append("revoked: " + ", ".join(revoked))
    detail += "; ".join(parts) if parts else "no change"
    _erp_staff_audit(conn, user["email"], "staff.permissions_changed",
                     "staff", staff_id, detail)
    conn.commit()
    conn.close()
    return jsonify(ok=True, staff_id=staff_id, perms=new_perms)


@app.get("/api/erp/session")
def erp_session_info():
    """Current caller's ERP role + permissions, for menu/route gating.
    Admins get the full grantable list; staff get their assigned grants."""
    role = _erp_role()
    if role == "admin":
        return jsonify(role="admin", perms=list(_ERP_GRANTABLE_PERMS))
    if role == "staff":
        staff = _staff_from_request()
        return jsonify(role="staff",
                       perms=_erp_staff_perms(staff["id"]) if staff else [])
    if role == "wholesale":
        return jsonify(role="wholesale", perms=[])
    return jsonify(error="login required"), 401

# ---------------- Storefront login handoff (Nov 2026) ----------------
# The storefront signs the admin in only through the shared pal_session
# cookie, which is third-party from pop-a-licious.com — browsers that block
# third-party cookies show the admin logged out after clicking "View
# storefront" in the ERP. The ERP mints a short-lived single-use code; the
# storefront redeems it for the admin's session token. Only the SHA-256 hash
# of a code is stored, never the code itself. The redeemed token is the
# minter's own session token: the cookie token and the Bearer <redacted> are the
# same _issue_auth_token value, and it is what /api/auth/me accepts.
HANDOFF_TTL_SECONDS = 60


@app.post("/api/erp/auth/handoff")
def erp_auth_handoff():
    actor, err = _require_erp_admin()
    if err:
        return err
    auth = request.headers.get("Authorization", "")
    token = auth[7:] if auth.lower().startswith("bearer ") else ""
    token = token or _session_token_from_request()
    user = _auth_user_from_token(token)
    if not user:
        return jsonify(error="login required"), 401
    code = secrets.token_urlsafe(32)
    now = datetime.now(timezone.utc).isoformat()
    conn = db()
    conn.execute(
        "INSERT INTO erp_login_codes (code_hash, token, email, created_at, used)"
        " VALUES (?, ?, ?, ?, 0)",
        (hashlib.sha256(code.encode()).hexdigest(), token,
         user["email"], now))
    conn.commit()
    conn.close()
    return jsonify(code=code)


# ---------------- Marketing emails (promos + merch drops) ----------------
# Audience = deduplicated: active+verified users + order emails (Stripe +
# PayPal), minus unsubscribes. Admin-gated sends. Every email carries a
# one-click unsubscribe link (HMAC-signed) + the business address.

MARKETING_FROM = os.environ.get("EMAIL_FROM", "Pop-A-Licious <noreply@pop-a-licious.com>")
MARKETING_ADDRESS_HTML = ("Pop-A-Licious, 2013 Angel Falls Dr., Henderson, NV 89074")

def _unsub_token(email):
    sig = hmac.new(RESEND_API_KEY.encode(), email.lower().encode(), hashlib.sha256).digest()
    return base64.urlsafe_b64encode(sig).decode().rstrip("=")

def _verify_unsub_token(email, token):
    try:
        return hmac.compare_digest(_unsub_token(email), token)
    except Exception:
        return False

def _marketing_audience(conn):
    """Deduplicated marketing audience: one email per address."""
    emails = {}
    for row in conn.execute(
            "SELECT email, name FROM users WHERE active = 1 AND verified = 1 AND email != ''"):
        emails[row["email"].lower()] = {"email": row["email"], "name": row["name"] or ""}
    for row in conn.execute(
            "SELECT DISTINCT email FROM orders WHERE email IS NOT NULL AND email != ''"):
        emails.setdefault(row["email"].lower(), {"email": row["email"], "name": ""})
    for row in conn.execute(
            "SELECT DISTINCT email FROM paypal_orders WHERE email IS NOT NULL AND email != ''"):
        emails.setdefault(row["email"].lower(), {"email": row["email"], "name": ""})
    for row in conn.execute(
            "SELECT email FROM newsletter_subscribers WHERE active = 1 AND email != ''"):
        emails.setdefault(row["email"].lower(), {"email": row["email"], "name": ""})
    unsub = {r["email"] for r in conn.execute("SELECT email FROM marketing_unsubscribes")}
    return [v for k, v in emails.items() if k not in unsub]

def _marketing_email_html(body_html, email):
    token = _unsub_token(email)
    qs = urlencode({"email": email, "token": token})
    unsub_url = f"https://pop-a-licious.com/api/marketing/unsubscribe?{qs}"
    return f"""{body_html}
<hr style="border:none;border-top:1px solid #ddd;margin:24px 0;">
<p style="font-size:12px;color:#888;">You're receiving this because you're a Pop-A-Licious customer.<br>
<a href="{unsub_url}" style="color:#888;">Unsubscribe</a> &nbsp;|&nbsp; {MARKETING_ADDRESS_HTML}</p>"""

def _send_marketing_batch(batch):
    """batch: list of dicts {to, subject, html}. Uses Resend batch endpoint (max 100)."""
    resp = requests.post(
        "https://api.resend.com/emails/batch",
        headers={"Authorization": f"Bearer {RESEND_API_KEY}", "Content-Type": "application/json"},
        json=[
            {
                "from": MARKETING_FROM,
                "to": [item["to"]],
                "subject": item["subject"],
                "html": item["html"],
                "headers": {"List-Unsubscribe": f"<{item['unsub_url']}>"},
                # Newsletter sends stamp their campaign_key so Resend
                # webhook events join back to the issue (Dept 8 item 6).
                **({"tags": [{"name": "campaign_key",
                              "value": item["campaign_key"]}]}
                   if item.get("campaign_key") else {}),
            }
            for item in batch
        ],
        timeout=30,
    )
    resp.raise_for_status()
    return resp.json()

@app.post("/api/admin/marketing/audience")
def admin_marketing_audience():
    """Return the deduplicated marketing audience count (admin preview before sending)."""
    user = _current_member()
    if not _is_admin(user):
        return jsonify(error="admin required"), 403
    conn = db()
    audience = _marketing_audience(conn)
    conn.close()
    return jsonify(count=len(audience))

@app.post("/api/admin/marketing/send")
def admin_marketing_send():
    """Send a marketing email to the deduplicated audience. Admin only.
    Body: {name, subject, html_body}. html_body is the inner content; footer
    with unsubscribe + address is appended automatically."""
    user = _current_member()
    if not _is_admin(user):
        return jsonify(error="admin required"), 403
    data = request.get_json(force=True) or {}
    name = (data.get("name") or "").strip()[:120]
    subject = (data.get("subject") or "").strip()
    html_body = data.get("html_body") or ""
    if not subject or not html_body:
        return jsonify(error="subject and html_body are required"), 400
    conn = db()
    audience = _marketing_audience(conn)
    sent = 0
    for i in range(0, len(audience), 100):
        chunk = audience[i:i + 100]
        batch = []
        for person in chunk:
            email = person["email"]
            token = _unsub_token(email)
            qs = urlencode({"email": email, "token": token})
            unsub_url = f"https://pop-a-licious.com/api/marketing/unsubscribe?{qs}"
            batch.append({
                "to": email,
                "subject": subject,
                "html": _marketing_email_html(html_body, email),
                "unsub_url": unsub_url,
            })
        try:
            _send_marketing_batch(batch)
            sent += len(batch)
        except Exception as e:
            conn.close()
            return jsonify(error=f"send failed after {sent} emails: {e}"), 502
    conn.execute(
        "INSERT INTO marketing_campaigns (name, subject, audience, recipient_count, sent_at)"
        " VALUES (?, ?, 'all', ?, ?)",
        (name, subject, sent, datetime.now(timezone.utc).isoformat()),
    )
    conn.commit()
    conn.close()
    return jsonify(ok=True, sent=sent, campaign=name)

@app.get("/api/admin/marketing/campaigns")
def admin_marketing_campaigns():
    """List past marketing campaigns (admin)."""
    user = _current_member()
    if not _is_admin(user):
        return jsonify(error="admin required"), 403
    conn = db()
    rows = conn.execute(
        "SELECT id, name, subject, recipient_count, sent_at FROM marketing_campaigns"
        " ORDER BY id DESC LIMIT 50").fetchall()
    conn.close()
    return jsonify(campaigns=[dict(r) for r in rows])

