@app.post("/api/erp/orders/<source>/<int:order_id>/edi-856")
def erp_order_edi856(source, order_id):
    """Generate an 856 ship-notice X12 for an order (queued for transport)."""
    actor, err = _erp_check_perm("edi.write")
    if err:
        return err
    data = request.get_json(force=True, silent=True) or {}
    if source not in _ERP_ORDER_SOURCES:
        return jsonify(error="unknown source"), 404
    conn = db()
    order = _erp_order_brief(conn, source, order_id)
    if not order:
        conn.close()
        return jsonify(error="order not found"), 404
    partner = None
    if data.get("partner_id"):
        partner = conn.execute("SELECT * FROM erp_edi_partners WHERE id = ?",
                               (data["partner_id"],)).fetchone()
    if not partner:
        partner = conn.execute("SELECT * FROM erp_edi_partners WHERE active = 1"
                               " ORDER BY id LIMIT 1").fetchone()
    if not partner:
        conn.close()
        return jsonify(error="no EDI partner configured"), 400
    cfg = _edi_config(conn, partner)
    if source == "wholesale":
        wlines = conn.execute("SELECT * FROM erp_wholesale_order_lines"
                              " WHERE order_id = ? ORDER BY id",
                              (order_id,)).fetchall()
        lines = [{"line": i + 1, "qty": float(l["qty_bags"]),
                  "product_id": (l["flavor_name"] or "")[:30].upper().replace(" ", "_"),
                  "description": l["flavor_name"]}
                 for i, l in enumerate(wlines)]
        ship_name = order.get("account_name") or order.get("customer_name")
    else:
        lines = [{"line": 1, "qty": float(order.get("total_qty") or 0),
                  "product_id": (order.get("number") or "").replace("#", ""),
                  "description": (order.get("items_summary") or "")[:60]}]
        ship_name = order.get("customer_name") or order.get("email")
    if not lines or sum(l["qty"] for l in lines) <= 0:
        conn.close()
        return jsonify(error="order has no shippable quantity"), 400
    o = {"number": order["number"], "po_number": order["number"],
         "ship_to": {"name": (ship_name or "Customer")[:40],
                     "qualifier": "92", "id": str(order_id)}}
    cartons = _edi_split_cartons(lines)
    if not cartons:
        conn.close()
        return jsonify(error="order has no shippable quantity"), 400
    prefix = _edi_map_value(cfg, "sscc_company_prefix", _EDI_SSCC_COMPANY_PREFIX)
    ssccs = [_edi_sscc_for(conn, source, order_id, i + 1, prefix)
             for i in range(len(cartons))]
    ctrl = _edi_next_control(conn)
    x12 = _x12_build_856(o, cartons, ssccs, cfg, ctrl,
                         test_mode=_edi_test_mode(partner))
    now = datetime.now(timezone.utc).isoformat()
    cur = conn.execute(
        "INSERT INTO erp_edi_documents (partner_id, direction, doc_type, status,"
        " raw_text, parsed_json, order_source, order_id, created_at)"
        " VALUES (?, 'outbound', '856', 'queued', ?, ?, ?, ?, ?)",
        (partner["id"], x12,
         json.dumps({"order_number": order["number"], "source": source,
                     "ssccs": ssccs, "cartons": len(cartons), "ctrl": ctrl,
                     "st02": "%04d" % (ctrl % 10000)}),
         source, order_id, now))
    d = conn.execute("SELECT * FROM erp_edi_documents WHERE id = ?",
                     (cur.lastrowid,)).fetchone()
    out = _edi_doc_dict(conn, d, include_content=True)
    conn.commit()
    conn.close()
    return jsonify(document=out), 201


@app.post("/api/erp/edi-documents/<int:doc_id>/send")
def erp_edi_send_document(doc_id):
    """Explicit-click transport delivery for a queued outbound doc.
    Never auto-sends on generation. api/webhook POST the stored X12 to the
    partner URL (test mode uses the configured test URL); sftp uses the
    system sftp CLI; manual-file returns the document for hand download and
    the doc stays queued (it has not been sent). Only queued docs can be
    sent; failed docs go through retry."""
    actor, err = _erp_check_perm("edi.write")
    if err:
        return err
    conn = db()
    d = conn.execute("SELECT * FROM erp_edi_documents WHERE id = ?",
                     (doc_id,)).fetchone()
    if not d:
        conn.close()
        return jsonify(error="document not found"), 404
    if d["direction"] != "outbound":
        conn.close()
        return jsonify(error="only outbound documents can be sent"), 400
    if d["status"] == "sent":
        conn.close()
        return jsonify(error="document already sent"), 400
    if d["status"] == "failed":
        conn.close()
        return jsonify(error="document failed — use retry to re-queue it"), 400
    if d["status"] != "queued":
        conn.close()
        return jsonify(error="only queued documents can be sent"), 400
    partner = conn.execute("SELECT * FROM erp_edi_partners WHERE id = ?",
                           (d["partner_id"],)).fetchone()
    if not partner:
        conn.close()
        return jsonify(error="no trading partner on this document"), 400
    cfg = _edi_config(conn, partner)
    transport = partner["transport"]
    if transport == "manual-file":
        conn.close()
        return jsonify(document=_edi_doc_dict_careful(d), download=True,
                       filename="edi-%s-%d.x12" % (d["doc_type"], d["id"]),
                       content=d["raw_text"])
    ok = False
    send_err = ""
    if transport in ("api", "webhook"):
        url = ""
        if _edi_test_mode(partner):
            url = (cfg.get("test_url") or "").strip()
        if not url:
            url = (cfg.get("url") or cfg.get("endpoint_url") or "").strip()
        if not url:
            conn.close()
            return jsonify(error="no send URL configured for partner"), 502
        try:
            status_code, _text = _edi_http_post(
                url, d["raw_text"], {"Content-Type": "application/EDI-X12"})
        except Exception as e:
            status_code = 0
            send_err = str(e)
        if 200 <= status_code < 300:
            ok = True
        elif not send_err:
            send_err = "HTTP %s from %s" % (status_code, url)
    elif transport == "sftp":
        ok, send_err = _edi_sftp_send(cfg, d["raw_text"])
    else:
        conn.close()
        return jsonify(error="unknown transport '%s'" % transport), 400
    if ok:
        conn.execute("UPDATE erp_edi_documents SET status = 'sent',"
                     " error_text = '' WHERE id = ?", (doc_id,))
        conn.commit()
    else:
        conn.execute("UPDATE erp_edi_documents SET status = 'failed',"
                     " error_text = ? WHERE id = ?", (send_err, doc_id))
        conn.commit()
    d = conn.execute("SELECT * FROM erp_edi_documents WHERE id = ?",
                     (doc_id,)).fetchone()
    conn.close()
    if ok:
        return jsonify(document=_edi_doc_dict_careful(d))
    return jsonify(document=_edi_doc_dict_careful(d),
                   error=send_err), 502


@app.get("/api/erp/edi/alerts")
def erp_edi_alerts():
    """Failed-doc alerting: total failed count + the failed docs (latest 50)."""
    actor, err = _erp_check_perm("edi.read")
    if err:
        return err
    conn = db()
    total = conn.execute(
        "SELECT COUNT(*) AS n FROM erp_edi_documents WHERE status = 'failed'"
        ).fetchone()["n"]
    rows = conn.execute(
        "SELECT * FROM erp_edi_documents WHERE status = 'failed'"
        " ORDER BY id DESC LIMIT 50").fetchall()
    out = [_edi_doc_dict(conn, d) for d in rows]
    conn.close()
    return jsonify(failed_count=total, failed=out)


@app.post("/api/erp/edi/retry-failed")
def erp_edi_retry_failed():
    """Cron-gated: re-queue failed outbound docs, max 3 attempts each.
    Docs at 3 attempts stay failed. No cron is created by this build;
    the cron is a deploy-time step. Same CRON_SECRET gate as the other
    cron endpoints (503 when unconfigured, 403 on mismatch)."""
    secret = os.environ.get("CRON_SECRET") or ""
    if not secret:
        return jsonify(error="cron not configured"), 503
    if request.headers.get("X-Cron-Secret") != secret:
        return jsonify(error="forbidden"), 403
    conn = db()
    rows = conn.execute(
        "SELECT * FROM erp_edi_documents WHERE status = 'failed'"
        " AND direction = 'outbound' ORDER BY id").fetchall()
    requeued = []
    skipped = []
    for d in rows:
        if int(d["retry_count"] or 0) >= 3:
            skipped.append(d["id"])
            continue
        conn.execute("UPDATE erp_edi_documents SET status = 'queued',"
                     " retry_count = retry_count + 1 WHERE id = ?", (d["id"],))
        requeued.append(d["id"])
    conn.commit()
    conn.close()
    return jsonify(requeued=requeued, skipped=skipped)


@app.get("/api/erp/edi-changes")
def erp_list_edi_changes():
    """Inbound 860 change records. Filter by order_id and/or status."""
    actor, err = _erp_check_perm("edi.read")
    if err:
        return err
    order_id = request.args.get("order_id", type=int)
    status = (request.args.get("status") or "").strip()
    conn = db()
    q = "SELECT * FROM erp_edi_changes WHERE 1=1"
    args = []
    if order_id:
        q += " AND order_id = ?"
        args.append(order_id)
    if status:
        if status not in ("pending", "accepted", "rejected"):
            conn.close()
            return jsonify(error="unknown status"), 400
        q += " AND status = ?"
        args.append(status)
    q += " ORDER BY id DESC"
    out = []
    for r in conn.execute(q, args).fetchall():
        try:
            change = json.loads(r["change_json"] or "{}")
        except (TypeError, ValueError):
            change = {}
        out.append({"id": r["id"], "doc_id": r["doc_id"],
                    "order_id": r["order_id"], "status": r["status"],
                    "created_at": r["created_at"], "change": change})
    conn.close()
    return jsonify(changes=out)


def _edi_change_decide(change_id, new_status):
    actor, err = _erp_check_perm("edi.write")
    if err:
        return err
    conn = db()
    r = conn.execute("SELECT * FROM erp_edi_changes WHERE id = ?",
                     (change_id,)).fetchone()
    if not r:
        conn.close()
        return jsonify(error="change not found"), 404
    if r["status"] != "pending":
        conn.close()
        return jsonify(error="change is already %s" % r["status"]), 400
    conn.execute("UPDATE erp_edi_changes SET status = ? WHERE id = ?",
                 (new_status, change_id))
    conn.commit()
    r = conn.execute("SELECT * FROM erp_edi_changes WHERE id = ?",
                     (change_id,)).fetchone()
    try:
        change = json.loads(r["change_json"] or "{}")
    except (TypeError, ValueError):
        change = {}
    conn.close()
    return jsonify(change={"id": r["id"], "doc_id": r["doc_id"],
                           "order_id": r["order_id"], "status": r["status"],
                           "created_at": r["created_at"], "change": change})


@app.post("/api/erp/edi-changes/<int:change_id>/accept")
def erp_accept_edi_change(change_id):
    """Accept a pending 860 change. Records the decision only — the order
    itself is NOT modified here; staff apply an accepted change to the
    order by hand through the normal order flow."""
    return _edi_change_decide(change_id, "accepted")


@app.post("/api/erp/edi-changes/<int:change_id>/reject")
def erp_reject_edi_change(change_id):
    """Reject a pending 860 change. Records the decision only."""
    return _edi_change_decide(change_id, "rejected")


@app.post("/api/erp/edi-webhook/<partner_key>")
def erp_edi_webhook(partner_key):
    """Provider push receiver. Key-authenticated ONLY (no login session).
    Accepts JSON {"content": "<X12>"} or a raw X12 body."""
    conn = db()
    digest = _edi_key_hash(partner_key or "")
    partner = None
    for p in conn.execute("SELECT * FROM erp_edi_partners WHERE active = 1"
                          " AND transport = 'webhook'").fetchall():
        cfg = _edi_config(conn, p)
        stored = cfg.get("webhook_key_hash") or ""
        if stored and hmac.compare_digest(stored, digest):
            partner = p
            break
    if not partner:
        conn.close()
        return jsonify(error="invalid partner key"), 401
    data = request.get_json(force=True, silent=True) or {}
    content = data.get("content") or ""
    if not content and request.data:
        try:
            content = request.data.decode("utf-8", "ignore")
        except Exception:
            content = ""
    if not content.strip():
        conn.close()
        return jsonify(error="X12 content is required"), 400
    doc, preview = _edi_parse_and_store_inbound(conn, partner, content,
                                               "edi-webhook")
    if doc is None:
        conn.close()
        return jsonify(error=preview), 400
    mapped_order = None
    if preview and not preview.get("errors") and preview.get("account_name"):
        try:
            parsed = json.loads(doc["parsed_json"] or "{}")
        except (TypeError, ValueError):
            parsed = {}
        mapped_order, map_err = _edi_map_850_to_order(conn, doc, parsed, partner,
                                                     "edi-webhook")
        if map_err:
            preview["errors"] = (preview.get("errors") or []) + [map_err]
    conn.commit()
    doc = conn.execute("SELECT * FROM erp_edi_documents WHERE id = ?",
                       (doc["id"],)).fetchone()
    status = doc["status"]
    doc_id = doc["id"]
    conn.close()
    resp = {"ok": True, "document_id": doc_id, "status": status}
    if mapped_order:
        resp["order"] = mapped_order
    return jsonify(resp), 201


# ================= ERP Phase 4: Reporting + QuickBooks bridge =================
# Spec: files/phase-4-spec.md. All endpoints admin-only (spec section 6).

# ---------- report helpers ----------

def _erp_report_dates(args):
    """Returns (date_from, date_to) as YYYY-MM-DD strings or ('','')."""
    df = (args.get("from") or "").strip()[:10]
    dt = (args.get("to") or "").strip()[:10]
    for d in (df, dt):
        if d and not re.match(r"^\d{4}-\d{2}-\d{2}$", d):
            return None, None
    return df, dt


def _erp_date_where(df, dt, col="created_at"):
    where = []
    params = []
    if df:
        where.append("substr(%s, 1, 10) >= ?" % col)
        params.append(df)
    if dt:
        where.append("substr(%s, 1, 10) <= ?" % col)
        params.append(dt)
    return (" AND ".join(where), params)


def _erp_parse_summary_flavors(items_summary):
    """Best-effort parse of '2x Cheddar, 1x Caramel' into [(qty, name)].

    Skips shipping chunks. Names are kept as-is (variety packs, merch).
    """
    out = []
    for chunk in re.split(r"[;\n]", items_summary or ""):
        for part in chunk.split(","):
            part = part.strip()
            if not part:
                continue
            m = re.match(r"^(\d+)\s*x\s+(.+)$", part, re.IGNORECASE)
            if not m:
                continue
            name = m.group(2).strip()
            if not name or name.lower().startswith("shipping"):
                continue
            try:
                out.append((int(m.group(1)), name[:120]))
            except ValueError:
                pass
    return out


def _erp_online_bags(r):
    """Bag count for an online sales row: parse items_summary; fall back to
    total_qty only when the summary parses to 0 (empty/unparseable). The
    Stripe webhook stores total_qty from session metadata, which is 0 on
    rows whose metadata never carried it (live order #1001) — items_summary
    is correct there, and the by-flavor table + forecast already count from
    the same parse."""
    parsed = sum(q for q, _ in _erp_parse_summary_flavors(r["items_summary"]))
    if parsed:
        return parsed
    return int(r["total_qty"] or 0)


def _erp_csv_response(filename, header, rows):
    import csv
    import io
    buf = io.StringIO()
    w = csv.writer(buf)
    w.writerow(header)
    for r in rows:
        w.writerow(r)
    resp = app.response_class(buf.getvalue(), mimetype="text/csv")
    resp.headers["Content-Disposition"] = "attachment; filename=%s" % filename
    return resp


def _erp_flavor_key(name):
    """Grouping key for a flavor name: strip a trailing ' Popcorn', trim,
    lowercase. 'Caramel Popcorn' and 'caramel' group together."""
    n = (name or "").strip()
    if n.lower().endswith(" popcorn"):
        n = n[: -len(" Popcorn")].strip()
    return n.lower()


def _erp_flavor_display(name):
    """Display name for a flavor: strip a trailing ' Popcorn', keep casing."""
    n = (name or "").strip()
    if n.lower().endswith(" popcorn"):
        n = n[: -len(" Popcorn")].strip()
    return n


def _erp_online_sales_rows(conn, df, dt):
    """Online sales rows for a period, de-duplicated exactly like the Sales
    report: orders excluding paypal-sourced copies UNION ALL captured
    paypal_orders. Each row carries src, email, items_summary,
    amount_total_cents, total_qty, created_at, gift_card_discount_cents,
    promo_code, reward_code."""
    where, params = _erp_date_where(df, dt)
    orders_where = "stripe_session_id NOT LIKE 'paypal:%'"
    if where:
        orders_where += " AND " + where
    q = ("SELECT id, 'stripe' AS src, email, items_summary, amount_total_cents,"
         " total_qty, created_at, gift_card_discount_cents, promo_code, reward_code"
         " FROM orders WHERE " + orders_where
         + " UNION ALL SELECT id, 'paypal' AS src, email, items_summary,"
         " amount_total_cents, total_qty, created_at, gift_card_discount_cents,"
         " promo_code, reward_code FROM paypal_orders WHERE status = 'captured'"
         + (" AND " + where if where else ""))
    return conn.execute(q, params + params).fetchall()


def _erp_blended_cost_per_bag(conn):
    """Blended production cost per bag across ALL completed batches
    (all-time basis): total_cost_cents / actual_qty_bags.
    Returns (cents_per_bag or None, batch_count, bags_produced,
    total_cost_cents)."""
    r = conn.execute(
        "SELECT COUNT(*) AS n, COALESCE(SUM(actual_qty_bags), 0) AS bags,"
        " COALESCE(SUM(total_cost_cents), 0) AS cost"
        " FROM erp_production_batches"
        " WHERE status = 'completed' AND actual_qty_bags > 0").fetchone()
    bags = float(r["bags"] or 0)
    if bags <= 0:
        return None, int(r["n"] or 0), 0, int(r["cost"] or 0)
    return (int(r["cost"] or 0) / bags), int(r["n"] or 0), bags, int(r["cost"] or 0)


def _erp_sales_breakdown(conn, df, dt, channel, online_rows):
    """Discount / refund / shipping / tax breakdown for the Sales report.
    Every figure comes from data the backend actually stores; anything not
    stored is None with a note explaining why — never estimated."""
    b = {
        "discounts": {
            "gift_card_cents": 0, "promo_code_orders": 0, "reward_code_orders": 0,
            "note": ("Only gift-card discounts are stored in cents on orders. "
                     "Promo-code and reward-code discount amounts are not tracked "
                     "anywhere — only the count of orders that used one.")},
        "refunds": {
            "wholesale_credits_cents": 0, "wholesale_returns_credited": 0,
            "retail_refunds_cents": 0,
            "note": ("Refunds are not offered — replacement or exchange only — "
                     "so retail refunds are always $0 and no retail refund "
                     "records exist.")},
        "shipping": {
            "wholesale_label_cost_cents": None, "online_label_cost_cents": None,
            "collected_cents": None,
            "note": ("Wholesale shipping cost is the Shippo label rate stored "
                     "when the label is created. Online label rates are "
                     "discarded after label creation and shipping collected is "
                     "not stored on orders, so both are not tracked.")},
        "tax": {
            "collected_cents": None,
            "note": ("Sales tax collected is not stored on orders; Nevada tax "
                     "is computed in Accounting (Phase 1, not yet deployed).")},
    }
    if channel in ("all", "online") and online_rows is not None:
        for r in online_rows:
            b["discounts"]["gift_card_cents"] += int(r["gift_card_discount_cents"] or 0)
            if (r["promo_code"] or "").strip():
                b["discounts"]["promo_code_orders"] += 1
            if (r["reward_code"] or "").strip():
                b["discounts"]["reward_code_orders"] += 1
    if channel in ("all", "wholesale"):
        w, p = _erp_date_where(df, dt, "r.created_at")
        row = conn.execute(
            "SELECT COALESCE(SUM(credit_cents), 0) AS c, COUNT(*) AS n"
            " FROM erp_wholesale_returns r WHERE r.status = 'credited'"
            + (" AND " + w if w else ""), p).fetchone()
        b["refunds"]["wholesale_credits_cents"] = int(row["c"] or 0)
        b["refunds"]["wholesale_returns_credited"] = int(row["n"] or 0)
        w2, p2 = _erp_date_where(df, dt, "shippo_label_created_at")
        row = conn.execute(
            "SELECT COALESCE(SUM(shipping_cents), 0) AS c"
            " FROM erp_wholesale_orders WHERE shippo_label_url != ''"
            + (" AND " + w2 if w2 else ""), p2).fetchone()
        b["shipping"]["wholesale_label_cost_cents"] = int(row["c"] or 0)
    return b


# ---------- report: sales by flavor/channel ----------

@app.get("/api/erp/reports/sales")
def erp_report_sales():
    actor, err = _erp_check_perm("reports.read")
    if err:
        return err
    df, dt = _erp_report_dates(request.args)
    if df is None:
        return jsonify(error="from/to must be YYYY-MM-DD"), 400
    channel = (request.args.get("channel") or "all").strip().lower()
    if channel not in ("all", "online", "wholesale"):
        return jsonify(error="channel must be all, online, or wholesale"), 400
    fmt = (request.args.get("format") or "json").strip().lower()
    conn = db()
    where, params = _erp_date_where(df, dt)
    online = {"order_count": 0, "total_cents": 0, "flavors": []}
    wholesale = {"order_count": 0, "total_cents": 0, "flavors": []}
    csv_rows = []
    online_rows = None
    if channel in ("all", "online"):
        # A captured PayPal order is copied into orders by the capture
        # (stripe_session_id 'paypal:<id>'), so the orders side must exclude
        # paypal-sourced rows or this UNION ALL counts the order twice.
        # _erp_online_sales_rows applies exactly that rule.
        rows = _erp_online_sales_rows(conn, df, dt)
        online_rows = rows
        flavors = {}
        for r in rows:
            online["order_count"] += 1
            online["total_cents"] += int(r["amount_total_cents"] or 0)
            for qty, name in _erp_parse_summary_flavors(r["items_summary"]):
                flavors[name] = flavors.get(name, 0) + qty
            if fmt == "csv":
                csv_rows.append(["online", r["src"], "%s-%d" % (r["src"], r["id"]),
                                (r["created_at"] or "")[:10], r["email"] or "",
                                r["items_summary"] or "", _erp_online_bags(r),
                                r["amount_total_cents"] or 0])
        online["flavors"] = [{"flavor": k, "bags": v}
                             for k, v in sorted(flavors.items(), key=lambda kv: -kv[1])]
    if channel in ("all", "wholesale"):
        q = ("SELECT o.id, o.order_number, o.created_at, a.name AS account_name,"
             " COALESCE(SUM(l.line_total_cents), 0) AS total_cents,"
             " COALESCE(SUM(l.qty_bags), 0) AS bags"
             " FROM erp_wholesale_orders o"
             " JOIN erp_wholesale_accounts a ON a.id = o.account_id"
             " LEFT JOIN erp_wholesale_order_lines l ON l.order_id = o.id"
             + (" WHERE " + where.replace("created_at", "o.created_at") if where else "")
             + " GROUP BY o.id ORDER BY o.id")
        rows = conn.execute(q, params).fetchall()
        flavors = {}
        for r in rows:
            wholesale["order_count"] += 1
            wholesale["total_cents"] += int(r["total_cents"] or 0)
            for ln in conn.execute(
                    "SELECT flavor_name, qty_bags, line_total_cents"
                    " FROM erp_wholesale_order_lines WHERE order_id = ?",
                    (r["id"],)).fetchall():
                f = flavors.setdefault(ln["flavor_name"], {"bags": 0, "total_cents": 0})
                f["bags"] += float(ln["qty_bags"] or 0)
                f["total_cents"] += int(ln["line_total_cents"] or 0)
            if fmt == "csv":
                csv_rows.append(["wholesale", "wholesale", r["order_number"],
                                (r["created_at"] or "")[:10], r["account_name"] or "",
                                "", r["bags"] or 0, r["total_cents"] or 0])
        wholesale["flavors"] = [{"flavor": k, "bags": v["bags"], "total_cents": v["total_cents"]}
                                for k, v in sorted(flavors.items(), key=lambda kv: -kv[1]["bags"])]
    breakdown = _erp_sales_breakdown(conn, df, dt, channel, online_rows)
    conn.close()
    if fmt == "csv":
        for _label, _val in [
                ("discounts: gift cards", breakdown["discounts"]["gift_card_cents"]),
                ("discounts: promo-code orders (count)",
                 breakdown["discounts"]["promo_code_orders"]),
                ("discounts: reward-code orders (count)",
                 breakdown["discounts"]["reward_code_orders"]),
                ("refunds: wholesale credits",
                 breakdown["refunds"]["wholesale_credits_cents"]),
                ("refunds: retail", breakdown["refunds"]["retail_refunds_cents"]),
                ("shipping: wholesale label cost",
                 breakdown["shipping"]["wholesale_label_cost_cents"]),
                ("shipping: online label cost",
                 breakdown["shipping"]["online_label_cost_cents"]),
                ("tax collected", breakdown["tax"]["collected_cents"])]:
            csv_rows.append(["breakdown", "", _label, "", "", _label, 0,
                             "" if _val is None else _val])
        return _erp_csv_response(
            "erp-sales-%s-%s.csv" % (df or "all", dt or "all"),
            ["channel", "source", "order_ref", "date", "customer",
             "items_summary", "bags", "total_cents"],
            csv_rows)
    return jsonify({
        "from": df, "to": dt, "channel": channel,
        "online": online, "wholesale": wholesale,
        "order_count": online["order_count"] + wholesale["order_count"],
        "total_cents": online["total_cents"] + wholesale["total_cents"],
        "breakdown": breakdown,
    })


def _erp_customer_rows(conn, df="", dt=""):
    """One row per customer, shared keying for the Reports customers
    endpoint and the Marketing CRM (Dept 8 item 2): retail keyed by
    normalized lowercase email from _erp_online_sales_rows (orders +
    captured paypal_orders, uncaptured PayPal excluded), wholesale
    keyed by account email — or by account when it has no email.
    Returns the customers dict (no repeat flag, no sorting)."""
    customers = {}

    def _add(key, display, email, account_name, order_dt, bags, spent):
        c = customers.get(key)
        if c is None:
            c = {"key": key, "display": display, "email": email or "",
                 "account_name": account_name or "", "order_count": 0,
                 "total_bags": 0, "total_spent_cents": 0,
                 "first_order_at": None, "last_order_at": None}
            customers[key] = c
        c["order_count"] += 1
        c["total_bags"] += bags
        c["total_spent_cents"] += spent
        d = (order_dt or "")[:10]
        if d:
            if not c["first_order_at"] or d < c["first_order_at"]:
                c["first_order_at"] = d
            if not c["last_order_at"] or d > c["last_order_at"]:
                c["last_order_at"] = d

    for r in _erp_online_sales_rows(conn, df, dt):
        email = (r["email"] or "").strip().lower()
        if email:
            _add("email:" + email, email, email, "", r["created_at"],
                 float(_erp_online_bags(r)), int(r["amount_total_cents"] or 0))
        else:
            _add("email:", "(no email)", "", "", r["created_at"],
                 float(_erp_online_bags(r)), int(r["amount_total_cents"] or 0))
    where, params = _erp_date_where(df, dt, "o.created_at")
    q = ("SELECT o.id, o.created_at, a.id AS account_id, a.name AS account_name,"
         " a.email AS account_email, COALESCE(SUM(l.qty_bags), 0) AS bags,"
         " COALESCE(SUM(l.line_total_cents), 0) AS spent"
         " FROM erp_wholesale_orders o"
         " JOIN erp_wholesale_accounts a ON a.id = o.account_id"
         " LEFT JOIN erp_wholesale_order_lines l ON l.order_id = o.id"
         + (" WHERE " + where if where else "")
         + " GROUP BY o.id ORDER BY o.id")
    for r in conn.execute(q, params).fetchall():
        email = (r["account_email"] or "").strip().lower()
        if email:
            _add("email:" + email, email, email, r["account_name"], r["created_at"],
                 float(r["bags"] or 0), int(r["spent"] or 0))
        else:
            _add("account:%d" % r["account_id"], r["account_name"], "",
                 r["account_name"], r["created_at"],
                 float(r["bags"] or 0), int(r["spent"] or 0))
    return customers


# ---------- report: customers / retention ----------

@app.get("/api/erp/reports/customers")
def erp_report_customers():
    """One row per customer: retail keyed by normalized lowercase email
    (orders + captured paypal_orders, uncaptured PayPal excluded), wholesale
    keyed by account email — or by account when it has no email. Repeat =
    2+ orders. Not a CRM: a simple customer list with repeat rate + LTV."""
    actor, err = _erp_check_perm("reports.read")
    if err:
        return err
    df, dt = _erp_report_dates(request.args)
    if df is None:
        return jsonify(error="from/to must be YYYY-MM-DD"), 400
    fmt = (request.args.get("format") or "json").strip().lower()
    conn = db()
    customers = _erp_customer_rows(conn, df, dt)
    conn.close()
    rows = sorted(customers.values(), key=lambda c: -c["total_spent_cents"])
    for c in rows:
        c["repeat"] = c["order_count"] >= 2
    total = len(rows)
    repeat = sum(1 for c in rows if c["repeat"])
    total_spent = sum(c["total_spent_cents"] for c in rows)
    summary = {
        "total_customers": total,
        "repeat_customers": repeat,
        "repeat_rate_pct": round(repeat / total * 100, 1) if total else 0.0,
        "avg_lifetime_value_cents": int(round(total_spent / total)) if total else 0,
        "total_spent_cents": total_spent,
    }
    if fmt == "csv":
        return _erp_csv_response(
            "erp-customers-%s-%s.csv" % (df or "all", dt or "all"),
            ["customer", "email", "account", "orders", "bags", "total_spent_cents",
             "first_order", "last_order", "repeat"],
            [[c["display"], c["email"], c["account_name"], c["order_count"],
              c["total_bags"], c["total_spent_cents"],
              c["first_order_at"] or "", c["last_order_at"] or "",
              "yes" if c["repeat"] else "no"] for c in rows])
    return jsonify({"from": df, "to": dt, "summary": summary, "customers": rows})


# ---------- report: channel profitability ----------

@app.get("/api/erp/reports/channel-profitability")
def erp_report_channel_profitability():
    """Per-channel revenue, cost of goods, shipping cost, payment fees, net.
    COGS uses the blended production cost per bag across all completed
    batches (all-time basis). Payment fees are not stored anywhere, so they
    are null with a footnote — never estimated from a published rate.
    Online shipping cost is not tracked either (retail label rates are
    discarded after label creation); wholesale shipping cost is the Shippo
    label rate stored when the label is created. Net is revenue minus the
    costs that are actually tracked; net_excludes lists what it leaves out.
    The Faire row appears only when Faire orders exist in the period;
    wholesale here is non-Faire wholesale (the Sales report groups Faire
    under wholesale)."""
    actor, err = _erp_check_perm("reports.read")
    if err:
        return err
    df, dt = _erp_report_dates(request.args)
    if df is None:
        return jsonify(error="from/to must be YYYY-MM-DD"), 400
    fmt = (request.args.get("format") or "json").strip().lower()
    conn = db()
    blended, n_batches, prod_bags, prod_cost = _erp_blended_cost_per_bag(conn)
    online_rows = _erp_online_sales_rows(conn, df, dt)
    online_rev = sum(int(r["amount_total_cents"] or 0) for r in online_rows)
    online_bags = sum(float(_erp_online_bags(r)) for r in online_rows)
    where, params = _erp_date_where(df, dt, "o.created_at")
    wrows = conn.execute(
        "SELECT o.id, o.via_faire, COALESCE(SUM(l.qty_bags), 0) AS bags,"
        " COALESCE(SUM(l.line_total_cents), 0) AS rev"
        " FROM erp_wholesale_orders o"
        " LEFT JOIN erp_wholesale_order_lines l ON l.order_id = o.id"
        + (" WHERE " + where if where else "")
        + " GROUP BY o.id", params).fetchall()
    ws_rev = ws_bags = f_rev = f_bags = 0
    for r in wrows:
        if int(r["via_faire"] or 0):
            f_rev += int(r["rev"] or 0)
            f_bags += float(r["bags"] or 0)
        else:
            ws_rev += int(r["rev"] or 0)
            ws_bags += float(r["bags"] or 0)
    w2, p2 = _erp_date_where(df, dt, "shippo_label_created_at")

    def _ship_cost(faire):
        row = conn.execute(
            "SELECT COALESCE(SUM(shipping_cents), 0) AS c"
            " FROM erp_wholesale_orders WHERE shippo_label_url != ''"
            " AND via_faire = ?" + (" AND " + w2 if w2 else ""),
            [1 if faire else 0] + p2).fetchone()
        return int(row["c"] or 0)

    ws_ship = _ship_cost(False)
    f_ship = _ship_cost(True)
    conn.close()

    def _chan(name, rev, bags, ship):
        cogs = round(bags * blended, 2) if blended is not None else None
        net = None
        if cogs is not None:
            net = round(rev - cogs - (ship or 0), 2)
        excl = ["payment fees (not tracked)"]
        if ship is None:
            excl.append("shipping cost (not tracked)")
        return {"channel": name, "revenue_cents": rev, "bags": bags,
                "cogs_cents": cogs, "shipping_cost_cents": ship,
                "fees_cents": None, "net_cents": net,
                "net_margin_pct": round(net / rev * 100, 1)
                if (net is not None and rev) else None,
                "net_excludes": excl}

    channels = [_chan("online", online_rev, online_bags, None),
                _chan("wholesale", ws_rev, ws_bags, ws_ship)]
    if f_rev or f_bags:
        channels.append(_chan("faire", f_rev, f_bags, f_ship))
    notes = [
        "Cost of goods uses the blended production cost per bag across all "
        "completed batches (all-time basis); no per-flavor cost is assumed.",
        "Payment processing fees are not stored anywhere, so net profit "
        "excludes them.",
        "Online shipping cost is not tracked: Shippo label rates for retail "
        "orders are discarded after label creation.",
    ]
    if fmt == "csv":
        return _erp_csv_response(
            "erp-channel-profitability-%s-%s.csv" % (df or "all", dt or "all"),
            ["channel", "revenue_cents", "bags", "cogs_cents",
             "shipping_cost_cents", "fees_cents", "net_cents", "net_margin_pct"],
            [[c["channel"], c["revenue_cents"], c["bags"],
              "" if c["cogs_cents"] is None else c["cogs_cents"],
              "" if c["shipping_cost_cents"] is None else c["shipping_cost_cents"],
              "", "" if c["net_cents"] is None else c["net_cents"],
              "" if c["net_margin_pct"] is None else c["net_margin_pct"]]
             for c in channels])
    return jsonify({
        "from": df, "to": dt,
        "blended_cost_per_bag_cents":
            round(blended, 2) if blended is not None else None,
        "cost_basis": {"completed_batches": n_batches,
                       "bags_produced": prod_bags,
                       "total_cost_cents": prod_cost},
        "channels": channels, "notes": notes,
    })


# ---------- report: programs (gift cards / subscriptions / fundraisers) ----------

@app.get("/api/erp/reports/programs")
def erp_report_programs():
    """Gift-card, subscription, and fundraiser totals, each from the tables
    that actually exist in this codebase. Demo rows (is_demo=1) are excluded
    everywhere. Gift-card liability is the live sum of active card balances.
    Fundraiser totals count paid orders only."""
    actor, err = _erp_check_perm("reports.read")
    if err:
        return err
    df, dt = _erp_report_dates(request.args)
    if df is None:
        return jsonify(error="from/to must be YYYY-MM-DD"), 400
    fmt = (request.args.get("format") or "json").strip().lower()
    conn = db()
    w, p = _erp_date_where(df, dt)
    gc_issued = conn.execute(
        "SELECT COUNT(*) AS n, COALESCE(SUM(amount_cents), 0) AS amt"
        " FROM gift_cards WHERE is_demo = 0"
        + (" AND " + w if w else ""), p).fetchone()
    w2, p2 = _erp_date_where(df, dt, "red.created_at")
    gc_red = conn.execute(
        "SELECT COUNT(*) AS n, COALESCE(SUM(red.amount_cents), 0) AS amt"
        " FROM redemptions red JOIN gift_cards g ON g.code = red.code"
        " WHERE g.is_demo = 0" + (" AND " + w2 if w2 else ""), p2).fetchone()
    gc_out = conn.execute(
        "SELECT COUNT(*) AS n, COALESCE(SUM(balance_cents), 0) AS amt"
        " FROM gift_cards WHERE is_demo = 0 AND active = 1").fetchone()
    gift_cards = {
        "issued_count": int(gc_issued["n"] or 0),
        "issued_cents": int(gc_issued["amt"] or 0),
        "redeemed_count": int(gc_red["n"] or 0),
        "redeemed_cents": int(gc_red["amt"] or 0),
        "active_count": int(gc_out["n"] or 0),
        "outstanding_cents": int(gc_out["amt"] or 0),
    }
    subs = {r["status"]: int(r["n"] or 0) for r in conn.execute(
        "SELECT status, COUNT(*) AS n FROM subscriptions"
        " WHERE is_demo = 0 GROUP BY status").fetchall()}
    w3, p3 = _erp_date_where(df, dt, "charged_at")
    ren = conn.execute(
        "SELECT COUNT(*) AS n, COALESCE(SUM(amount_cents), 0) AS amt"
        " FROM subscription_renewals WHERE status = 'charged'"
        + (" AND " + w3 if w3 else ""), p3).fetchone()
    subscriptions = {
        "active": subs.get("active", 0),
        "paused": subs.get("paused", 0),
        "cancelled": subs.get("cancelled", 0),
        "total": sum(subs.values()),
        "renewals_charged_count": int(ren["n"] or 0),
        "renewals_charged_cents": int(ren["amt"] or 0),
    }
    fundraisers = []
    for f in conn.execute(
            "SELECT id, code, org_name, goal_cents, status, created_at"
            " FROM fundraisers ORDER BY created_at").fetchall():
        w4, p4 = _erp_date_where(df, dt, "created_at")
        per = conn.execute(
            "SELECT COUNT(*) AS n, COALESCE(SUM(total_cents), 0) AS tot,"
            " COALESCE(SUM(donation_cents), 0) AS don,"
            " COALESCE(SUM(roundup_cents), 0) AS rnd"
            " FROM fundraiser_orders WHERE fundraiser_id = ? AND status = 'paid'"
            + (" AND " + w4 if w4 else ""),
            [f["id"]] + p4).fetchone()
        all_t = conn.execute(
            "SELECT COALESCE(SUM(total_cents), 0) AS tot FROM fundraiser_orders"
            " WHERE fundraiser_id = ? AND status = 'paid'", (f["id"],)).fetchone()
        raised_all = int(all_t["tot"] or 0)
        goal = int(f["goal_cents"] or 0)
        fundraisers.append({
            "id": f["id"], "code": f["code"], "org_name": f["org_name"],
            "status": f["status"], "goal_cents": goal,
            "orders": int(per["n"] or 0),
            "raised_cents": int(per["tot"] or 0),
            "donation_cents": int(per["don"] or 0),
            "roundup_cents": int(per["rnd"] or 0),
            "raised_all_time_cents": raised_all,
            "progress_pct": round(raised_all / goal * 100, 1) if goal else None,
        })
    conn.close()
    if fmt == "csv":
        rows = [
            ["gift_cards", "issued", gift_cards["issued_count"],
             gift_cards["issued_cents"], "in period"],
            ["gift_cards", "redeemed", gift_cards["redeemed_count"],
             gift_cards["redeemed_cents"], "in period"],
            ["gift_cards", "outstanding liability", gift_cards["active_count"],
             gift_cards["outstanding_cents"], "live balance on active cards"],
            ["subscriptions", "active", subscriptions["active"], "", "now"],
            ["subscriptions", "cancelled", subscriptions["cancelled"], "", "now"],
            ["subscriptions", "renewals charged",
             subscriptions["renewals_charged_count"],
             subscriptions["renewals_charged_cents"], "in period"],
        ]
        for f in fundraisers:
            rows.append(["fundraisers", "%s (%s)" % (f["org_name"], f["code"]),
                         f["orders"], f["raised_cents"],
                         "in period; all-time %d, goal %d" % (
                             f["raised_all_time_cents"], f["goal_cents"])])
        return _erp_csv_response(
            "erp-programs-%s-%s.csv" % (df or "all", dt or "all"),
            ["section", "label", "count", "amount_cents", "note"], rows)
    return jsonify({"from": df, "to": dt, "gift_cards": gift_cards,
                    "subscriptions": subscriptions, "fundraisers": fundraisers})


def _erp_forecast_flavors(conn):
    """Shared forecast computation: Reports forecast + Production MRP.

    Returns {generated_on, window_start, window_end, buckets, flavors,
    note}: per-flavor bags/week over the last 8 weeks (online orders +
    captured PayPal + wholesale lines, same de-duplication as the Sales
    report), 4-week average velocity, projection = velocity x 4. A simple
    average projection only: no seasonality, no trend adjustment, no
    confidence figure. The canonical flavor list comes from
    erp_flavor_categories, so flavors with no recent sales still appear,
    flagged has_recent_sales=False. Names not in the catalog (variety
    packs, merch) appear as their own rows."""
    today = datetime.now(timezone.utc).date()
    buckets = []
    for i in range(7, -1, -1):
        end = today - timedelta(days=7 * i)
        start = end - timedelta(days=6)
        buckets.append({"label": "%s to %s" % (start.isoformat(), end.isoformat()),
                        "start": start.isoformat(), "end": end.isoformat()})
    window_start = buckets[0]["start"]
    window_end = buckets[-1]["end"]
    sales = {}

    def _add(name, qty, date_str):
        key = _erp_flavor_key(name)
        if not key:
            return
        try:
            d = datetime.strptime((date_str or "")[:10], "%Y-%m-%d").date()
        except ValueError:
            return
        delta = (today - d).days
        if delta < 0 or delta > 55:
            return
        b = 7 - (delta // 7)
        entry = sales.get(key)
        if entry is None:
            entry = {"display": _erp_flavor_display(name), "weekly": [0.0] * 8}
            sales[key] = entry
        entry["weekly"][b] += float(qty or 0)

    for r in _erp_online_sales_rows(conn, window_start, window_end):
        for qty, name in _erp_parse_summary_flavors(r["items_summary"]):
            _add(name, qty, r["created_at"])
    for r in conn.execute(
            "SELECT o.created_at, l.flavor_name, l.qty_bags"
            " FROM erp_wholesale_order_lines l"
            " JOIN erp_wholesale_orders o ON o.id = l.order_id"
            " WHERE substr(o.created_at, 1, 10) >= ?"
            " AND substr(o.created_at, 1, 10) <= ?",
            (window_start, window_end)).fetchall():
        _add(r["flavor_name"], r["qty_bags"], r["created_at"])

    def _row(flavor, category, weekly):
        total = sum(weekly)
        vel = sum(weekly[-4:]) / 4
        return {"flavor": flavor, "category": category,
                "weekly_bags": [round(x, 1) for x in weekly],
                "total_bags_8w": round(total, 1),
                "velocity_4w": round(vel, 2),
                "projection_4w": round(vel * 4, 1),
                "has_recent_sales": total > 0}

    flavors = []
    for row in conn.execute(
            "SELECT flavor_name, category FROM erp_flavor_categories"
            " ORDER BY flavor_name").fetchall():
        key = _erp_flavor_key(row["flavor_name"])
        entry = sales.pop(key, None)
        flavors.append(_row(row["flavor_name"], row["category"],
                            entry["weekly"] if entry else [0.0] * 8))
    for key in sorted(sales):
        entry = sales[key]
        flavors.append(_row(entry["display"], "", entry["weekly"]))
    note = ("Simple average projection: 4-week average weekly velocity x 4 "
            "weeks. No seasonality or trend adjustment; flavors with no sales "
            "in the last 8 weeks are flagged.")
    return {"generated_on": today.isoformat(),
            "window_start": window_start, "window_end": window_end,
            "buckets": buckets, "flavors": flavors, "note": note}


# ---------- report: demand forecast ----------

@app.get("/api/erp/reports/forecast")
def erp_report_forecast():
    """Per-flavor demand forecast (see _erp_forecast_flavors, shared with
    the Production MRP so the two can never disagree on velocity)."""
    actor, err = _erp_check_perm("reports.read")
    if err:
        return err
    fmt = (request.args.get("format") or "json").strip().lower()
    conn = db()
    data = _erp_forecast_flavors(conn)
    conn.close()
    if fmt == "csv":
        header = ["flavor", "category"] +             ["week_%d_bags" % (i + 1) for i in range(8)] +             ["total_bags_8w", "velocity_4w", "projection_4w", "has_recent_sales"]
        return _erp_csv_response(
            "erp-forecast-%s.csv" % data["generated_on"], header,
            [[f["flavor"], f["category"]] + f["weekly_bags"] +
             [f["total_bags_8w"], f["velocity_4w"], f["projection_4w"],
              "yes" if f["has_recent_sales"] else "no"] for f in data["flavors"]])
    return jsonify(data)


# ---------- report: inventory valuation ----------

@app.get("/api/erp/reports/inventory-valuation")
def erp_report_inventory_valuation():
    actor, err = _erp_check_perm("reports.read")
    if err:
        return err
    fmt = (request.args.get("format") or "json").strip().lower()
    conn = db()
    rows = conn.execute(
        "SELECT i.id, i.sku, i.name, i.type, l.code AS location_code,"
        " l.name AS location_name, SUM(s.qty_change) AS on_hand,"
        " i.avg_cost_cents"
        " FROM erp_stock_ledger s"
        " JOIN erp_items i ON i.id = s.item_id"
        " JOIN erp_locations l ON l.id = s.location_id"
        " GROUP BY i.id, l.id HAVING on_hand != 0"
        " ORDER BY i.type, i.name, l.code").fetchall()
    items = []
    total_cents = 0
    for r in rows:
        on_hand = float(r["on_hand"] or 0)
        avg = int(r["avg_cost_cents"] or 0)
        value_cents = int(round(on_hand * avg))
        total_cents += value_cents
        items.append({
            "sku": r["sku"], "name": r["name"], "type": r["type"],
            "location_code": r["location_code"], "location_name": r["location_name"],
            "on_hand": on_hand, "avg_cost_cents": avg, "value_cents": value_cents,
        })
    conn.close()
    if fmt == "csv":
        return _erp_csv_response(
            "erp-inventory-valuation.csv",
            ["sku", "name", "type", "location", "on_hand",
             "avg_cost_cents", "value_cents"],
            [[i["sku"], i["name"], i["type"], i["location_code"],
              i["on_hand"], i["avg_cost_cents"], i["value_cents"]] for i in items])
    return jsonify({"items": items, "total_cents": total_cents,
                    "item_count": len(items)})


# ---------- report: production cost & margin ----------

@app.get("/api/erp/reports/production-margin")
def erp_report_production_margin():
    actor, err = _erp_check_perm("reports.read")
    if err:
        return err
    fmt = (request.args.get("format") or "json").strip().lower()
    df, dt = _erp_report_dates(request.args)
    if df is None:
        return jsonify(error="from/to must be YYYY-MM-DD"), 400
    where, params = _erp_date_where(df, dt, "b.completed_at")
    conn = db()
    rows = conn.execute(
        "SELECT r.id AS recipe_id, r.name AS flavor, r.batch_size_bags,"
        " COUNT(b.id) AS batches, COALESCE(SUM(b.actual_qty_bags), 0) AS bags,"
        " COALESCE(SUM(b.total_cost_cents), 0) AS cost_cents,"
        " COALESCE(SUM(b.ingredient_cost_cents), 0) AS ingredient_cents,"
        " COALESCE(SUM(b.labor_cost_cents), 0) AS labor_cents,"
        " COALESCE(SUM(b.overhead_cents), 0) AS overhead_cents"
        " FROM erp_production_batches b"
        " JOIN erp_recipes r ON r.id = b.recipe_id"
        " WHERE b.status = 'completed' AND b.actual_qty_bags > 0"
        + (" AND " + where if where else "")
        + " GROUP BY r.id ORDER BY r.name", params).fetchall()
    flavors = []
    for r in rows:
        bags = float(r["bags"] or 0)
        cost_cents = int(r["cost_cents"] or 0)
        cpb = (cost_cents / bags) if bags else 0
        flavors.append({
            "flavor": r["flavor"], "batches": r["batches"],
            "bags_produced": bags,
            "cost_per_bag_cents": round(cpb, 2),
            "ingredient_cost_cents": int(r["ingredient_cents"] or 0),
            "labor_cost_cents": int(r["labor_cents"] or 0),
            "overhead_cents": int(r["overhead_cents"] or 0),
            "retail_price_cents": 800,
            "retail_margin_cents": round(800 - cpb, 2),
            "retail_margin_pct": round((800 - cpb) / 800 * 100, 1) if cpb else 100.0,
            "wholesale_price_cents": 400,
            "wholesale_margin_cents": round(400 - cpb, 2),
            "wholesale_margin_pct": round((400 - cpb) / 400 * 100, 1) if cpb else 100.0,
        })
    conn.close()
    note = ("Wholesale price uses the default $4.00/bag; per-account prices may vary. "
            "Retail is $8.00/bag. Batch cost includes ingredients + labor + "
            "overhead (labor + overhead are batch actuals only; recipe/BOM cost "
            "stays ingredients + packaging).")
    if fmt == "csv":
        return _erp_csv_response(
            "erp-production-margin.csv",
            ["flavor", "batches", "bags_produced", "cost_per_bag_cents",
             "ingredient_cost_cents", "labor_cost_cents", "overhead_cents",
             "retail_price_cents", "retail_margin_cents", "retail_margin_pct",
             "wholesale_price_cents", "wholesale_margin_cents",
             "wholesale_margin_pct"],
            [[f["flavor"], f["batches"], f["bags_produced"],
              f["cost_per_bag_cents"], f["ingredient_cost_cents"],
              f["labor_cost_cents"], f["overhead_cents"], f["retail_price_cents"],
              f["retail_margin_cents"], f["retail_margin_pct"],
              f["wholesale_price_cents"], f["wholesale_margin_cents"],
              f["wholesale_margin_pct"]] for f in flavors])
    return jsonify({"from": df, "to": dt, "flavors": flavors, "note": note})


