        "SELECT a.id, a.name, a.email, a.phone, a.price_per_bag_cents,"
        " COUNT(DISTINCT o.id) AS order_count,"
        " COALESCE(SUM(l.line_total_cents), 0) AS revenue_cents,"
        " MAX(o.created_at) AS last_order_at"
